package com.aicharacter.v3;
/** Arrival -> physical target when required -> action -> learned outcome. Observation may be non-contact. */
public final class PlanExecutor{private PlanExecutor(){}
 public static void onArrival(WorldState s,TravelState travel,long now){PlanState p=s.planState;if(p==null||!"girl".equals(travel.actor)||!p.planId.equals(travel.currentPlanId))return;p.lastArrival=("LOCAL".equals(travel.travelMode)?travel.targetId:travel.destinationArea)+" @"+now;p.lastProgressAt=now;if("find_cat".equals(p.intentionId)){GirlCatSearchEngine.onArrival(s,now);return;}if("LOCAL".equals(travel.travelMode)){executeAction(s,now);return;}WorldObject target=resolveTarget(s,p);if(requiresContact(p.plannedAction)&&target!=null&&!PhysicalInteraction.inRangeForAction(s,target,p.plannedAction)){p.lastAction="approaching "+target.id;float tx=PhysicalInteraction.targetXForAction(s,target,"girl",s.haruX,p.plannedAction);if(!TravelEngine.startLocal(s,s.girlTravel,"girl",target.id,tx,PhysicalInteraction.rangeForAction(target,p.plannedAction),p.planId,now)){failPlan(s,p,now,"object target not physically reachable");}return;}executeAction(s,now);}
 private static WorldObject resolveTarget(WorldState s,PlanState p){WorldObject t=s.world.object(p.destination);if(t!=null)return t;if("REST_PROTECT".equals(p.plannedAction))return s.world.firstTagged("rest");if("REFLECT".equals(p.plannedAction))return s.world.firstTagged("reflect");return null;}
 private static boolean requiresContact(String action){return"REST_PROTECT".equals(action)||"REFLECT".equals(action);}
 private static String routeDestination(WorldState s,PlanState p){if(p==null)return"";WorldObject target=s.world.object(p.destination);if(target!=null)return target.areaId;WorldArea area=s.world.area(p.destination);return area==null?"":area.id;}
 public static void executeAction(WorldState s,long now){PlanState p=s.planState;if(p==null||!"ACTIVE".equals(p.status))return;String action=p.plannedAction;WorldObject target=resolveTarget(s,p);if(requiresContact(action)&&(target==null||!PhysicalInteraction.inRangeForAction(s,target,action))){p.lastOutcome="blocked: target outside interaction range";if(target!=null){float tx=PhysicalInteraction.targetXForAction(s,target,"girl",s.haruX,action);if(!TravelEngine.startLocal(s,s.girlTravel,"girl",target.id,tx,PhysicalInteraction.rangeForAction(target,p.plannedAction),p.planId,now))failPlan(s,p,now,"object target not physically reachable");}else failPlan(s,p,now,"required interaction target no longer exists");return;}boolean ok=true;String outcome;if("REST_PROTECT".equals(action)){ok=WorldInteractionEngine.interact(s,target,"REST");outcome=ok?"reached a protected place to rest":"rest interaction failed";}else if("REFLECT".equals(action)){ok=WorldInteractionEngine.interact(s,target,"REFLECT");if(ok)s.mood.pleasantness=Math.min(1,s.mood.pleasantness+.08);outcome=ok?"quiet reflection completed":"reflection target unavailable";}else if("OBSERVE".equals(action)){WorldArea area=s.world.area(routeDestination(s,p));ok=area!=null;if(ok){s.emotion.curiosity=Math.max(0,s.emotion.curiosity-.025);s.mood.pleasantness=Math.min(1,s.mood.pleasantness+.025);}outcome=ok?(target!=null?"observed "+target.id+" without controlling or touching it":"observed "+area.id):"observation area unavailable";}else{outcome="no executable action: "+action;ok=false;}p.lastAction=action+" @"+now;p.lastOutcome=outcome;p.status=ok?"COMPLETED":"FAILED";if(ok)p.stepIndex=p.steps.size();p.lastProgressAt=now;MemoryEntry learned=CognitionEngine.process(s,new Experience("planned_action_outcome",p.intentionId+": "+outcome,ok?.12:-.12,ok?.42:.5).atTime(now).at(HaruPerception.currentPlaceId(s),target==null?p.destination:target.id).tag(p.intentionId).tag(ok?"success":"failure"));AdaptiveBeliefEngine.observePlanOutcome(s,p,ok,learned);if(ok)completeVisibleAction(s,p,now);else{s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.haruActivity="pausing after something did not work";}}
 private static void failPlan(WorldState s,PlanState p,long now,String outcome){p.status="FAILED";p.lastOutcome=outcome;p.lastProgressAt=now;s.girlTravel.active=false;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.haruActivity="pausing after something became unreachable";}
 private static void completeVisibleAction(WorldState s,PlanState p,long now){s.girlTravel.active=false;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;p.lastReconsideredAt=now;String id=p.intentionId==null?"":p.intentionId;if("sleep".equals(id)){s.haruActivity="sleeping";return;}if("seek_shelter".equals(id)||"recover".equals(id)){s.haruActivity=s.body.energy<30||s.body.sleepiness>65?"resting":"settling after rest";return;}if("reflect".equals(id)||"quiet_pause".equals(id)){s.haruActivity="finishing a quiet thought";return;}if(id.startsWith("observe")||id.startsWith("watch")||id.startsWith("explore")){s.haruActivity="looking around after noticing something";return;}s.haruActivity="idle between intentions";}
 public static void applyDecision(WorldState s,PlanReconsiderationEngine.Result r,long now){PlanState p=s.planState;if(p==null)return;if(r.decision==PlanReconsiderationEngine.Decision.CONTINUE)return;if(r.decision==PlanReconsiderationEngine.Decision.PAUSE){p.status="PAUSED";p.pausedAt=now;p.pauseReason=r.reason;s.girlTravel.active=false;return;}if(r.decision==PlanReconsiderationEngine.Decision.REPLAN){p.status="ACTIVE";String dest=routeDestination(s,p);if(dest.isEmpty()||!TravelEngine.start(s,s.girlTravel,"girl",dest,p.planId,now)){p.status="FAILED";p.lastProgressAt=now;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.haruActivity="pausing after a plan became impossible";p.lastOutcome="replan failed: no valid route";MemoryEntry m=CognitionEngine.experience(s,now,"plan_replan_failed",p.intentionId+": route unavailable",-.18,.55,p.intentionId,"failure");AdaptiveBeliefEngine.observePlanOutcome(s,p,false,m);}}else{p.status="ABANDONED";p.lastProgressAt=now;s.girlTravel.active=false;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.haruActivity="hesitating after changing her mind";CognitionEngine.experience(s,now,"plan_abandoned",p.intentionId+": "+r.reason,-.04,.32,p.intentionId,"reconsidered");}}
 public static boolean resume(WorldState s,long now){PlanState p=s.planState;if(p==null||!"PAUSED".equals(p.status))return false;NeedState n=NeedState.evaluate(s);boolean restGoal="sleep".equals(p.intentionId)||"seek_shelter".equals(p.intentionId)||"recover".equals(p.intentionId);double bodyPressure=Math.max(n.safety,n.physicalComfort*.85)+Math.max(0,24-s.body.energy)*1.5+s.body.pain*.55;if(!restGoal&&bodyPressure>62)return false;if(s.body.energy<12&&!restGoal)return false;p.pauseReason="";p.lastDecision="RESUME: current needs allow the preserved plan to continue";if("find_cat".equals(p.intentionId))return GirlCatSearchEngine.resume(s,now);String dest=routeDestination(s,p);if(dest.isEmpty()){p.status="FAILED";p.lastProgressAt=now;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.haruActivity="pausing after a plan became impossible";p.lastOutcome="resume failed: destination no longer exists";return false;}p.status="ACTIVE";s.currentIntention=p.intentionId;s.persistentIntentionTarget=p.destination;s.intentionStartedAt=now;if(TravelEngine.start(s,s.girlTravel,"girl",dest,p.planId,now))return true;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;p.status="FAILED";p.lastProgressAt=now;s.haruActivity="pausing after a plan became impossible";p.lastOutcome="resume failed: no valid route";return false;}
}